begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(17);
insert into auth.users(id,email,raw_app_meta_data,raw_user_meta_data) values
('82000000-0000-4000-8000-000000000001','social-a@example.test','{"provider":"email"}','{"username":"social_a"}'),
('82000000-0000-4000-8000-000000000002','social-b@example.test','{"provider":"email"}','{"username":"social_b"}');
insert into public.feed_posts(author_id,body,created_at) select '82000000-0000-4000-8000-000000000001','Roadmap fixture Post '||i,now()-make_interval(secs=>i) from generate_series(1,25) i;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"82000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('test.cursor',public.community_read('feed','{"q":"Roadmap fixture Post "}')->>'nextCursor',true);
select is(jsonb_array_length(public.community_read('feed','{"q":"Roadmap fixture Post "}')->'items'),20,'First social page is bounded');
select public.community_mutate('post.create','{"body":"Roadmap fixture Post new arrival","clientId":"82000000-0000-4000-8000-000000000030"}');
select is(jsonb_array_length(public.community_read('feed',jsonb_build_object('cursor',current_setting('test.cursor'),'q','Roadmap fixture Post '))->'items'),5,'Inserting a new post does not shift the next page');
select throws_ok($$select public.community_read('feed',jsonb_build_object('cursor',current_setting('test.cursor'),'filter','popular'))$$,'22023',null,'Cursor cannot be reused for another filter');
select public.community_mutate('room.create','{"title":"Unlisted audit unique","body":"","category":"deep","private":false,"visibility":"unlisted","capacity":2}');
select is(jsonb_array_length(public.community_read('spaces','{"q":"Unlisted audit unique"}')->'items'),0,'Unlisted rooms never leak through public directory');
select public.community_mutate('buddy.save','{"title":"Study","body":"Read together","subjects":["Math"],"published":true,"category":"student","timezone":"Europe/Berlin","availability":"Weekends"}');
select is(public.community_read('buddies','{"filter":"student"}')->'items'->0->'data'->>'availability','Weekends','Discovery returns validated availability');
select is(jsonb_array_length(public.community_read('buddies','{"filter":"professional"}')->'items'),0,'Buddy categories filter server-side');
select public.community_mutate('group.create','{"title":"Private study","body":"","private":true}');
select set_config('test.group',(select id::text from public.study_groups where owner_id=auth.uid()),true);
select set_config('test.token',public.community_mutate('group.invite',jsonb_build_object('id',current_setting('test.group')))->>'token',true);
select set_config('test.invite',(public.community_read('invitations',jsonb_build_object('id',current_setting('test.group'),'filter','group'))->'items'->0->>'id'),true);
select public.community_mutate('group.invite.revoke',jsonb_build_object('id',current_setting('test.invite')));
select throws_ok($$select public.community_mutate('invite.accept',jsonb_build_object('token',current_setting('test.token')))$$,'42501',null,'Revoked group invitations cannot be accepted');
select public.community_mutate('event.create',jsonb_build_object('title','Virtual reading','startsAt',now()+interval '1 day','minutes',30,'capacity',1,'mode','private-characters','characterSlugs',jsonb_build_array('male-01'),'timezone','Europe/Berlin'));
select set_config('test.event',(select id::text from public.scheduled_sessions where creator_id=auth.uid()),true);
select is((select room_id from public.scheduled_sessions where id=current_setting('test.event')::uuid),null::uuid,'Private-character bookings create no human room');
select is(public.community_read('schedule')->'items'->0->'data'->>'schedulingTimezone','Europe/Berlin','Scheduling timezone survives profile changes');
select throws_ok($$select public.community_mutate('event.start',jsonb_build_object('id',current_setting('test.event')))$$,'42501',null,'Booking cannot start before its time');
select lives_ok($$select public.community_mutate('event.update',jsonb_build_object('id',current_setting('test.event'),'title','Read longer','startsAt',now()+interval '2 days','minutes',60,'capacity',1,'mode','private-characters','characterSlugs',jsonb_build_array('female-01'),'timezone','Europe/Berlin'))$$,'Owner can edit a future private schedule');
select is((select count(*) from public.sessions where user_id=auth.uid()),0::bigint,'Scheduling and editing never bank time');
select set_config('request.jwt.claims','{"sub":"82000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select is((select count(*) from jsonb_array_elements(public.community_read('schedule')->'items') item where item->>'id'=current_setting('test.event')),0::bigint,'Private-character bookings are isolated from other users');
select throws_ok($$select public.community_mutate('event.update',jsonb_build_object('id',current_setting('test.event'),'title','Read longer','startsAt',now()+interval '2 days','minutes',60,'capacity',1,'mode','private-characters','characterSlugs',jsonb_build_array('female-01'),'timezone','UTC'))$$,'42501',null,'Nonowner cannot edit a schedule');
select throws_ok($$select public.read_room_participants((select id from public.study_rooms limit 1))$$,'42501',null,'Participant pages require active room membership');
select public.community_mutate('preferences','{"leaderboardOptIn":true}');
select lives_ok($$select public.community_leaderboard('streak','week')$$,'Windowed streak ranking is available');
select is((select count(*) from public.user_achievements where user_id=auth.uid()),0::bigint,'Bookings do not mint achievements');
reset role;
select * from finish();
rollback;
